package io.aetheris.orchestrator.voice;import org.springframework.stereotype.Service;import java.util.*;@Service public class VoiceStreamingService {private final VoiceSessionRepository sessions;private final VoiceTurnMetricRepository metrics;private final SpeechAdapterCatalog adapters;public VoiceStreamingService(VoiceSessionRepository sessions,VoiceTurnMetricRepository metrics,SpeechAdapterCatalog adapters){this.sessions=sessions;this.metrics=metrics;this.adapters=adapters;}public VoiceTurnMetricEntity record(VoiceTurnMetricRequest r){if(r.sessionId()==null||!sessions.existsById(r.sessionId()))throw new IllegalArgumentException("Known voice session is required");return metrics.save(new VoiceTurnMetricEntity(UUID.randomUUID(),r));}public List<VoiceTurnMetricEntity> recent(){return metrics.findTop100ByOrderByCreatedAtDesc();}public Map<String,Object> adapters(){return adapters.status();}}
